//! Which atlas tile each block face shows. The atlas is packed by build.rs from
//! assets/images/blocks: a block named `grass` uses `grass.png`, and
//! `grass_top.png` / `grass_side.png` / `grass_bottom.png` override single faces.

use amity_protocol::world::block::Block;
use bevy::prelude::*;

/// The block texture atlas and its name -> tile table, generated by build.rs from
/// assets/images/blocks. Embedded so native and web load it the same way.
mod atlas {
    include!(concat!(env!("OUT_DIR"), "/atlas.rs"));
}
pub const ATLAS: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/atlas.png"));

/// The texture a block's faces use, as a file name in assets/images/blocks
/// without `.png`
fn block_texture(block: Block) -> &'static str {
    match block {
        Block::Air => "air",
        Block::Stone => "stone",
        Block::Dirt => "dirt",
        Block::Grass => "grass",
    }
}

/// Which atlas tile a face shows. A face-specific texture (`grass_top`,
/// `grass_side`, `grass_bottom`) beats the block's plain one; with neither, the
/// face shows the missing-texture checker.
pub fn face_tile(block: Block, normal: IVec3) -> u32 {
    let face = match normal {
        IVec3::Y => "top",
        IVec3::NEG_Y => "bottom",
        _ => "side",
    };
    let name = block_texture(block);
    tile_named(&format!("{name}_{face}"))
        .or_else(|| tile_named(name))
        .unwrap_or(atlas::MISSING)
}

fn tile_named(name: &str) -> Option<u32> {
    atlas::TILES
        .iter()
        .find(|(tile_name, _)| *tile_name == name)
        .map(|&(_, tile)| tile)
}

/// Maps a 0..1 face UV into `tile`'s rectangle of the atlas. Pulled in by a sliver
/// of a pixel so float rounding at a face's edge never samples the next tile; any
/// more than that crops the edge pixels and visibly shifts the texture.
pub fn tile_uv(tile: u32, [u, v]: [f32; 2]) -> [f32; 2] {
    let size = Vec2::new(1.0 / atlas::COLUMNS as f32, 1.0 / atlas::ROWS as f32);
    let inset = size / (64 * atlas::TILE_PIXELS) as f32;
    let corner = Vec2::new((tile % atlas::COLUMNS) as f32, (tile / atlas::COLUMNS) as f32) * size;
    [
        corner.x + inset.x + u * (size.x - 2.0 * inset.x),
        corner.y + inset.y + v * (size.y - 2.0 * inset.y),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::world::meshing::mesher::FACES;

    #[test]
    fn tile_uvs_stay_inside_their_tile() {
        let size = Vec2::new(1.0 / atlas::COLUMNS as f32, 1.0 / atlas::ROWS as f32);
        // tile 1 is column 1, row 0
        let [u0, v0] = tile_uv(1, [0.0, 0.0]);
        let [u1, v1] = tile_uv(1, [1.0, 1.0]);
        assert!(u0 > size.x && v0 > 0.0);
        assert!(u1 < 2.0 * size.x && v1 < size.y);
    }

    #[test]
    fn every_block_face_has_a_texture() {
        for block in [Block::Stone, Block::Dirt, Block::Grass] {
            for face in &FACES {
                assert_ne!(
                    face_tile(block, face.normal),
                    atlas::MISSING,
                    "{block:?} has no texture in assets/images/blocks"
                );
            }
        }
    }
}
